func FindUsageEvent(ctx context.Context, exec bob.Executor, IDPK uuid.UUID, cols ...string) (*UsageEvent, error) {
	if len(cols) == 0 {
		return UsageEvents.Query(
			sm.Where(UsageEvents.Columns.ID.EQ(psql.Arg(IDPK))),
		).One(ctx, exec)
	}

	return UsageEvents.Query(
		sm.Where(UsageEvents.Columns.ID.EQ(psql.Arg(IDPK))),
		sm.Columns(UsageEvents.Columns.Only(cols...)),
	).One(ctx, exec)
}

